module twos_complement(
  input [3:0] in,
  output [3:0] out
);

  assign out = ~in + 1;

endmodule

module d_latch (
  input D,
  input CLK,
  output Q,
  output Q_bar
);

reg Q;
reg Q_bar;

always @(posedge CLK)
begin
  Q <= D;
  Q_bar <= ~D;
end

endmodule

module twos_complement (
    input [3:0] num_in,
    output [3:0] num_out
);

    wire [3:0] inverted_num;
    wire [3:0] one = 4'b0001;

    assign inverted_num = ~num_in;
    assign num_out = inverted_num + one;

endmodule

module and_gate(
    input a, 
    input b,
    output reg out
);

    always @(*) begin
        out = (a & b) ? 1'b1 : 1'b0;
    end

endmodule

module calculator (input [7:0] A, input [7:0] B, input sel, output reg [7:0] result);

always @(*) begin
